-- Class notes synopsis batch 19: Olive through Pedicularis

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Olive</strong> leaf is an <strong>antimicrobial</strong> that inhibits <strong>H. pylori</strong> for <strong>peptic ulcer</strong>.$$
WHERE id = 106;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Onion</strong> (red onion) is an <strong>antibacterial</strong> and <strong>antiviral</strong> infection fighter used in traditional Black American herbalism alongside <a href="?herb=21"><strong>Garlic</strong></a>; noted for <strong>viral</strong> and <strong>bacterial infection</strong> in cancer support.$$
WHERE id = 208;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Oregano</strong> is a very <strong>antimicrobial</strong> culinary aromatic herb and volatile oil plant; inhibits <strong>H. pylori</strong> for <strong>peptic ulcer</strong>; used as oil capsules for recurrent infections including <strong>SIBO</strong> and <strong>candida</strong>. Wound wash <strong>antimicrobial</strong> alongside <a href="?herb=109"><strong>Rosemary</strong></a>, <a href="?herb=59"><strong>Thyme</strong></a>, <a href="?herb=302"><strong>Tea Tree</strong></a>, and <a href="?herb=44"><strong>Yarrow</strong></a>. Used in herbal steams for <strong>respiratory congestion</strong>; potential inhalation herb for <strong>bronchitis</strong> ("use what you have" - volatile oil plants with scent); also as a respiratory tea steam. 1 part Oregano (or <a href="?herb=59"><strong>Thyme</strong></a>) in herbal salt recipe.$$
WHERE id = 406;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Oregon Grape Root</strong> (Berberis aquifolium) is a berberine-containing <strong>cholagogue</strong>, <strong>bitter tonic</strong> (medium bitter; bright yellow from berberine - an alkaloid whose taste blooms slowly), broad <strong>antimicrobial</strong> (gram-negative: E. coli, Salmonella; gram-positive: Strep, Staph), <strong>antifungal</strong>, <strong>anti-inflammatory</strong>, and <strong>alterative</strong> with primary <strong>digestive system</strong> affinity (contrasted with <a href="?herb=112"><strong>Usnea</strong></a>'s urinary affinity). Stimulates bile release from the gallbladder. Specific indications: <strong>liver congestion</strong> and low bile, <strong>infectious hepatitis</strong> (Hep A), <strong>food poisoning</strong>, liver tenderness with slow digestion, <strong>skin eruptions</strong> (boils, acne, rashes, comedones) with coated tongue, <strong>SIBO/candida</strong> (penetrates biofilms), <strong>anti-protozoal</strong>, potentiates antibiotics (MRSA). Go-to for <strong>metabolic-associated fatty liver disease</strong> alongside <a href="?herb=203"><strong>Turmeric</strong></a> and liver herbs. Hepatic support for <strong>rheumatoid arthritis</strong>. Berberine-containing <strong>alterative</strong> for <strong>kidney</strong> and <strong>skin</strong> issues alongside <strong>insulin resistance</strong>; berberine-containing herb for <strong>blood sugar</strong> support in <strong>perimenopause</strong> (also <a href="?herb=158"><strong>Barberry</strong></a>); reduces blood sugar and cholesterol/lipid levels in <strong>PMOS</strong>. PCOS formula: Oregon Grape Root 30ml, <a href="?herb=78"><strong>Licorice</strong></a> 10ml, <a href="?herb=2238"><strong>White Peony</strong></a> 30ml, <a href="?herb=167"><strong>Cinnamon</strong></a> 20ml, <a href="?herb=2229"><strong>Gotu Kola</strong></a> 30ml; 4ml 2x/day. Drying herb; indicated for oily skin via berberines acting on the liver; skin deficiency: stimulates liver. For <strong>hot constitution</strong>: hot-reducing, liver-supporting, alterative bitter tonic. <strong>Upper GI deficiency</strong>: stimulate secretions alongside <a href="?herb=158"><strong>Barberry</strong></a>, <a href="?herb=102"><strong>Gentian</strong></a>, <a href="?herb=34"><strong>Bogbean</strong></a>. Wound wash <strong>antimicrobial</strong>; for cuts and open wounds: antimicrobial (berberine) and anti-inflammatory applied externally; for infected wounds: berberine-rich antimicrobial and astringent - "stop further decay of tissues and zap infection"; used both externally and internally; specific for <strong>abscess</strong> alongside <a href="?herb=30"><strong>Goldenseal</strong></a>. Primary topicals wound kit alongside <a href="?herb=99"><strong>Myrrh</strong></a> and <a href="?herb=32"><strong>Chaparral</strong></a>; protocol step 3 primary topical tincture with <a href="?herb=99"><strong>Myrrh</strong></a> (possibly). Immune support for microbial causes of <strong>diarrhea</strong> alongside <a href="?herb=26"><strong>Echinacea</strong></a> and <a href="?herb=23"><strong>Wild Indigo</strong></a>. Tincturing: fresh 1:2 80-95%, dry 1:5 50%; alkaloidal plant - needs 5-10% vinegar when tincturing.$$
WHERE id = 33;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Osha</strong> ("Bear Medicine") is a powerfully <strong>warming</strong> and <strong>drying</strong> <strong>stimulating expectorant</strong>, <strong>antiviral</strong> (inhibits viral replication), <strong>diaphoretic</strong>, <strong>bronchodilator</strong>, and powerful <strong>emmenagogue</strong>; member of the parsley family (looks like poison hemlock). Primary indication is <strong>cold/damp cough</strong> - warming and drying to match the cold and damp condition; dose 10-15 drops every few hours for cold/wet rattly cough. Bronchodilator for <strong>asthma</strong> alongside <a href="?herb=132"><strong>Lobelia</strong></a> and <a href="?herb=2643"><strong>Pine Needles</strong></a>. Stimulating expectorant alongside <a href="?herb=2231"><strong>Grindelia</strong></a> and <a href="?herb=590"><strong>Yerba Santa</strong></a> for Cold and Damp Lung. Antiviral for <strong>influenza</strong> - use at first sign of infection. For <strong>respiratory deficiency</strong>: increases mucus secretion in tissues. In Deep Lung Formula for <strong>bronchitis</strong>: <a href="?herb=54"><strong>Elecampane</strong></a>, <a href="?herb=65"><strong>Angelica</strong></a>, <a href="?herb=590"><strong>Yerba Santa</strong></a>, <a href="?herb=44"><strong>Yarrow</strong></a>, <a href="?herb=73"><strong>Hawthorn</strong></a>, <a href="?herb=61"><strong>Mullein</strong></a>, <a href="?herb=309"><strong>Yerba Mansa</strong></a>, <a href="?herb=21"><strong>Garlic</strong></a>, Osha. Applied topically to wounds. Specifically indicated for congestion (drying herb). <strong>Very drying antiviral - always balance with moistening herbs; overuse can dry the tissues, kill the microbes, but then produce a cough from the resulting dryness; use with damp/cool coughs, or add Marshmallow.</strong>$$
WHERE id = 104;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Parsley</strong> is a highly nutritive culinary herb; dried Parsley is very high in nutrients and a rich source of <strong>Vitamin C</strong>.$$
WHERE id = 120;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Pasqueflower</strong> (Pulsatilla / Anemone) is a <strong>drop dose</strong> <strong>anxiolytic nervine</strong>, <strong>vasodilator</strong>, and <strong>parasympathetic</strong> support herb. Specific for <strong>shock trauma</strong> - use 1-5 drops, can ground the person. For <strong>anxiety</strong>, <strong>anxiety-induced insomnia</strong>, and acute wind. Dose: MM range 3-10 drops 4x/day - use at the low end; David Hoffmann range 30-60 drops. For <strong>respiratory deficiency</strong>: increases parasympathetic function alongside <a href="?herb=132"><strong>Lobelia</strong></a> (small doses). For <strong>cardiovascular deficiency</strong>: vasodilator and parasympathetic support. For <strong>musculoskeletal deficiency</strong>: vascular stimulant. For <strong>female reproductive deficiency</strong>: stimulates HPA.$$
WHERE id = 36;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Passionflower</strong> is a <strong>GABA</strong>-supporting <strong>nervine sedative</strong>, <strong>relaxing nervine</strong>, <strong>anxiolytic</strong>, <strong>analgesic</strong>, and <strong>muscle relaxant</strong> - the primary "brake pedal" for the nervous system. Specific differential: <strong>circular thinking</strong> - helps the mind disconnect (like a "radio playing in your head"); for <strong>hypervigilance</strong>, <strong>racing thoughts</strong>, <strong>anxiety</strong>, and <strong>insomnia</strong>. For <strong>anxiety-induced insomnia</strong>, <strong>menopause-induced insomnia</strong>, and <strong>insomnia in pregnancy</strong> (sleep support during and after pregnancy) - better as a "sleep tonic" taken throughout the day so you are ready for the night, rather than only at bedtime; use usually not encouraged except in hours before bed. In sleep tincture with <a href="?herb=20"><strong>Ashwagandha</strong></a>. Nervine sedative for <strong>musculoskeletal excess</strong>: muscle relaxant. Nervine for <strong>rheumatoid arthritis</strong>. Calming nervine for <strong>asthma</strong> - interrupts the panic-asthma feedback cycle; included in base tincture. Sedative/anodyne for bone aches and body aches in <strong>influenza</strong>. For <strong>erectile dysfunction</strong>: anxiety/nervine support. In <strong>cancer</strong> support tea alongside CBD and <a href="?herb=203"><strong>Turmeric</strong></a>. Nervine alongside <a href="?herb=84"><strong>Chamomile</strong></a>, <a href="?herb=134"><strong>Lemon Balm</strong></a>, <a href="?herb=136"><strong>Catnip</strong></a>, <a href="?herb=142"><strong>Skullcap</strong></a>, <a href="?herb=983"><strong>Blue Vervain</strong></a>. Alkaloidal plant - alkaloids not well extracted by water alone; requires alcohol-based extraction for full therapeutic effect; needs 5-10% vinegar when tincturing.$$
WHERE id = 137;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Peach</strong> leaf is a <strong>cooling</strong>, underused <strong>nervine</strong>, <strong>anti-inflammatory</strong>, <strong>lymphatic</strong>, and <strong>cooling GI tonic</strong>; helps for <strong>nausea</strong> and anything hot; specific for <strong>hyperchlorhydria</strong>. For <strong>cancer</strong> support: relieves <strong>stomach pain</strong>, supports healthy <strong>elimination</strong>, and provides lymphatic and nervine support. Topical for <strong>bee stings</strong> and <strong>bug bites</strong>. Historical formula for <strong>chills</strong>, <strong>aches</strong>, and <strong>fever</strong>: Peach leaf with <a href="?herb=313"><strong>Sassafras</strong></a> and <a href="?herb=84"><strong>Chamomile</strong></a> (cami weed).$$
WHERE id = 320;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Pedicularis</strong> (Indian Warrior, Elephant Head, Parrot's Beak; Pedicularis densiflora and related species) is one of the strongest <strong>skeletal muscle relaxants</strong> available, rivaling <a href="?herb=138"><strong>Kava</strong></a>; wild-harvested and parasitic - it cannot be cultivated and requires specific host plants in intact ecosystems. First-line for <strong>tension release</strong>; specific for <strong>jaw tension</strong>, <strong>teeth grinding</strong> (higher dose to start to unwind: 60mL, then taper to 35-40mL), and <strong>muscle tension insomnia</strong>. Formula for <strong>acute muscle tension</strong>: Pedicularis, <a href="?herb=25"><strong>Black Cohosh</strong></a>, <a href="?herb=124"><strong>Ginger</strong></a>. Paired with <a href="?herb=2461"><strong>Jamaican Dogwood</strong></a> for <strong>skeletal muscle pain</strong>, often alongside <a href="?herb=25"><strong>Black Cohosh</strong></a> - Jamaican Dogwood addresses smooth muscle pain and nervous irritability while Pedicularis contributes direct skeletal muscle relaxation. <strong>Sustainability note: wild-harvested and cannot be cultivated; Kava is one of the few sustainable alternatives.</strong>$$
WHERE id = 2624;
